CREATE TABLE "SensorConnection" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"provider" TEXT NOT NULL,"externalId" TEXT,"status" TEXT NOT NULL DEFAULT 'pending',"lastSyncAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SensorConnection_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "SensorConnection_userId_provider_key" ON "SensorConnection"("userId","provider");ALTER TABLE "SensorConnection" ADD CONSTRAINT "SensorConnection_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;